// WebGLEngine/tools/ship/seaPatch.mjs -- UNNUMBERED (the version is chosen at ship time).
//
// *** STEP 2 OF ocean-src-integration: A PATCH LAYER, NOT AN EDIT. ***
// vendor/web-ocean/js/main.js stays upstream's bytes. world/ocean/seaMain.mjs is that file with the PATCHES below applied, generated by `node tools/ship/seaPatch.mjs --write` (it lives beside its gate in tools/ship; only the generated file is under world/) and held to
// its inputs by tools/ship/seaPatch-selfcheck.mjs: the upstream hash, every patch's anchor (each must occur exactly as often as the patch says), the patched hash, and the committed file
// equal to what applyPatches() makes of the vendored one. So the question "what did SweK change" is this list and nothing else.
//
// WHAT THE PATCHES DO, ALL OF IT:
//   imports   the five './wgsl/...' imports become absolute (/vendor/web-ocean/js/wgsl/...), so the patched module can live outside the vendor directory;
//   api       `export const seaApi` -- a handle on upstream's own parameter block P: setParams({key: value}) sets P[key] for every key P has (swellSpread INCLUDED, the one parameter with
//             no panel slider) and raises the flag upstream raises for it (needSpectrum for the wave spectrum, needLUT for haze); ready, waterHeight() and raise() are filled in by main()
//             once its flags exist;
//   hook      three lines after upstream's `let needSpectrum = true, needLUT = true, envFull = 2;` that give the api its closure over the flags and over waterH.
// WHAT THEY DO NOT DO, said plainly: no external canvas or camera (the sea still owns #c and its own camera), no height at an arbitrary point (waterHeight() is the height under the SEA'S camera,
// read back from the GPU a few frames late, which is all upstream computes), no depth composite. Those are the next steps. NOT SEEN HERE: any of it on a GPU.
"use strict";
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const UPSTREAM_PATH = "vendor/web-ocean/js/main.js";
export const PATCHED_PATH = "world/ocean/seaMain.mjs";
export const UPSTREAM_SHA256 = "ceca4404e1514cb8dd94990faf043bd8de2cb0fd201cbc2da803f150e34e3834";
export const PATCHED_SHA256 = "d0faa922233cc97e6362ba09e8203ede4951d1de0f0ba067da49f71297478ed0";

const SPEC_KEYS = "windSpeed,windDir,fetchKm,swellHs,swellLength,swellDir,swellSpread,choppy";

/** Each patch: id, the exact upstream text it anchors on, how many times that text occurs, and the text that replaces it. */
export const PATCHES = Object.freeze([
    { id: "imports", count: 5, find: "from './wgsl/", replace: "from '/vendor/web-ocean/js/wgsl/" },
    {
        id: "api", count: 1,
        find: "const CASC_L = [1103.0, 211.3, 39.7, 7.43, 1.393, 0.2617];\n",
        replace: "const CASC_L = [1103.0, 211.3, 39.7, 7.43, 1.393, 0.2617];\n" +
            "// SweK patch (tools/ship/seaPatch.mjs): the page's handle on the sea. P is upstream's block; raise/waterHeight/ready are filled in by main() once its flags exist.\n" +
            "export const seaApi = {\n" +
            "  P, ready: false, raise: null, waterHeight: null,\n" +
            "  SPEC: new Set('" + SPEC_KEYS + "'.split(',')),\n" +
            "  setParams(o) {\n" +
            "    const applied = [];\n" +
            "    for (const k of Object.keys(o || {})) {\n" +
            "      if (!(k in P) || !Number.isFinite(Number(o[k]))) continue;\n" +
            "      P[k] = Number(o[k]); applied.push(k);\n" +
            "    }\n" +
            "    if (this.raise) this.raise(applied.some((k) => this.SPEC.has(k)), applied.includes('haze'));\n" +
            "    return applied;\n" +
            "  },\n" +
            "};\n",
    },
    {
        id: "hook", count: 1,
        find: "  let needSpectrum = true, needLUT = true, envFull = 2;\n",
        replace: "  let needSpectrum = true, needLUT = true, envFull = 2;\n" +
            "  seaApi.raise = (spec, lut) => { if (spec) needSpectrum = true; if (lut) needLUT = true; envFull = 2; };\n" +
            "  seaApi.waterHeight = () => waterH;\n" +
            "  seaApi.ready = true;\n",
    },
]);

export const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");

/** Apply the patches to upstream's text. Throws if an anchor does not occur exactly `count` times -- a drifted upstream must not patch quietly. */
export function applyPatches(upstreamText, patches = PATCHES) {
    let out = String(upstreamText);
    for (const p of patches) {
        const n = out.split(p.find).length - 1;
        if (n !== p.count) throw new Error("patch '" + p.id + "': anchor occurs " + n + " times, expected " + p.count);
        out = out.split(p.find).join(p.replace);
    }
    return out;
}

/** The bench report: which patches, how many bytes each adds, and the two hashes. */
export function reportLines(upstreamText = null, patches = PATCHES) {
    const L = ["[seaPatch] " + patches.length + " patches on vendor/web-ocean/js/main.js (upstream sha256 " + UPSTREAM_SHA256.slice(0, 8) + "...)"];
    for (const p of patches) L.push("  " + p.id.padEnd(8) + " x" + p.count + "  " + (p.replace.length - p.find.length) * p.count + " bytes added per file");
    if (upstreamText != null) { const o = applyPatches(upstreamText, patches); L.push("  patched: " + o.length + " bytes, sha256 " + sha256(o).slice(0, 8) + "..."); }
    return L;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
    const ENG = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
    const up = fs.readFileSync(path.join(ENG, UPSTREAM_PATH));
    if (sha256(up) !== UPSTREAM_SHA256) { console.error("upstream main.js is not the pinned one"); process.exit(1); }
    const out = applyPatches(up.toString("utf8"));
    if (process.argv.includes("--write")) { fs.writeFileSync(path.join(ENG, PATCHED_PATH), out); console.log("wrote " + PATCHED_PATH + " " + out.length + " bytes sha256 " + sha256(out)); }
    else console.log(reportLines(up.toString("utf8")).join("\n"));
}
